#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <random>
#include <chrono>
#include <mutex>
#include <thread>
#include <stdexcept>
#include <openssl/evp.h>
#include <openssl/rand.h>

namespace chat {

struct SessionData {
    std::string user_id;
    std::string display_name;
    uint64_t created_at;
    uint64_t last_active;
    bool authenticated;
    std::vector<unsigned char> encryption_key;
};

class SessionStore {
private:
    std::unordered_map<std::string, SessionData> sessions_;
    std::mutex mtx_;

    std::string generate_token(size_t length = 32) {
        std::vector<unsigned char> buf(length);
        if (RAND_bytes(buf.data(), static_cast<int>(length)) != 1) {
            throw std::runtime_error("RAND_bytes failed: insufficient entropy");
        }
        std::string token;
        for (auto b : buf) {
            char hex[3];
            snprintf(hex, sizeof(hex), "%02x", b);
            token += hex;
        }
        return token;
    }

    std::vector<unsigned char> derive_key(const std::string& session_id) {
        std::vector<unsigned char> key(32);
        const unsigned char salt[] = "chat_server_v2_salt";
        if (PKCS5_PBKDF2_HMAC(session_id.c_str(), session_id.length(),
                          salt, sizeof(salt) - 1, 10000,
                          EVP_sha256(), 32, key.data()) != 1) {
            throw std::runtime_error("PBKDF2 key derivation failed");
        }
        return key;
    }

public:
    std::string create_session() {
        std::lock_guard<std::mutex> lock(mtx_);
        std::string token = generate_token();
        SessionData sd;
        sd.authenticated = false;
        sd.created_at = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        sd.last_active = sd.created_at;
        sd.encryption_key = derive_key(token);
        sessions_[token] = std::move(sd);
        return token;
    }

    std::string regenerate_session(const std::string& old_session_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(old_session_id);
        if (it == sessions_.end()) return "";

        SessionData old_data = std::move(it->second);
        sessions_.erase(it);

        std::string new_token = generate_token();
        old_data.encryption_key = derive_key(new_token);
        old_data.last_active = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        sessions_[new_token] = std::move(old_data);
        return new_token;
    }

    bool authenticate(const std::string& session_id, const std::string& user_id,
                     const std::string& display_name) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(session_id);
        if (it == sessions_.end()) return false;
        if (user_id.empty()) return false;

        it->second.user_id = user_id;
        it->second.display_name = display_name;
        it->second.authenticated = true;
        it->second.last_active = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        return true;
    }

    SessionData* get_session(const std::string& session_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(session_id);
        if (it == sessions_.end()) return nullptr;
        it->second.last_active = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        return &it->second;
    }

    bool is_valid_session_format(const std::string& token) {
        if (token.length() != 64) return false;
        for (char c : token) {
            if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return false;
        }
        return true;
    }
};

class ChatServer {
private:
    SessionStore store_;
    std::unordered_map<std::string, std::vector<std::string>> message_log_;
    std::mutex msg_mtx_;

    std::string encrypt_message(const std::vector<unsigned char>& key, const std::string& msg) {
        std::vector<unsigned char> iv(12);
        if (RAND_bytes(iv.data(), 12) != 1) {
            throw std::runtime_error("RAND_bytes failed: unable to generate IV");
        }

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            throw std::runtime_error("EVP_CIPHER_CTX_new failed");
        }

        std::vector<unsigned char> ciphertext(msg.size() + 16);
        int len = 0;
        int ct_len = 0;
        unsigned char tag[16];

        try {
            if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key.data(), iv.data()) != 1) {
                throw std::runtime_error("EVP_EncryptInit_ex failed");
            }
            if (EVP_EncryptUpdate(ctx, ciphertext.data(), &len,
                             reinterpret_cast<const unsigned char*>(msg.c_str()), msg.size()) != 1) {
                throw std::runtime_error("EVP_EncryptUpdate failed");
            }
            ct_len = len;
            if (EVP_EncryptFinal_ex(ctx, ciphertext.data() + len, &len) != 1) {
                throw std::runtime_error("EVP_EncryptFinal_ex failed");
            }
            ct_len += len;
            if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) {
                throw std::runtime_error("EVP_CTRL_GCM_GET_TAG failed");
            }
        } catch (...) {
            EVP_CIPHER_CTX_free(ctx);
            throw;
        }
        EVP_CIPHER_CTX_free(ctx);

        std::string result(iv.begin(), iv.end());
        result.append(ciphertext.begin(), ciphertext.begin() + ct_len);
        result.append(tag, tag + 16);
        return result;
    }

public:
    struct ConnectResult {
        bool success;
        std::string session_id;
        std::string error;
    };

    ConnectResult handle_connect(const std::string& client_token) {
        ConnectResult result;

        if (!client_token.empty() && store_.is_valid_session_format(client_token)) {
            SessionData* existing = store_.get_session(client_token);
            if (existing != nullptr && existing->authenticated) {
                result.success = true;
                result.session_id = client_token;
                return result;
            }
        }

        // Always generate a new server-side session for unauthenticated connections
        result.session_id = store_.create_session();
        result.success = true;
        return result;
    }

    bool handle_login(const std::string& session_id, const std::string& user,
                     const std::string& password, std::string& new_session_id) {
        // In production, verify against credential store with bcrypt/argon2
        if (user.empty() || password.length() < 8) return false;

        if (!store_.authenticate(session_id, user, user)) return false;

        // Regenerate session ID after authentication to prevent fixation
        new_session_id = store_.regenerate_session(session_id);
        return !new_session_id.empty();
    }

    bool send_message(const std::string& session_id, const std::string& channel,
                     const std::string& message) {
        SessionData* sd = store_.get_session(session_id);
        if (!sd || !sd->authenticated) return false;

        std::string encrypted = encrypt_message(sd->encryption_key, message);

        std::lock_guard<std::mutex> lock(msg_mtx_);
        message_log_[channel].push_back(encrypted);
        return true;
    }
};

} // namespace chat

int main() {
    chat::ChatServer server;

    // Simulate normal flow
    auto conn = server.handle_connect("");
    std::cout << "New session: " << conn.session_id << std::endl;

    std::string new_sid;
    server.handle_login(conn.session_id, "alice", "securepass123", new_sid);
    std::cout << "Post-auth session: " << new_sid << std::endl;

    server.send_message(new_sid, "general", "Hello everyone!");

    return 0;
}
